import {createFeedback} from './feedback.js';
let feedback;let reviewComments=[],catalogData=[];
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);const date=s=>new Date(s).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const paths={notifications:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',earnings:'M12 2v20M17 6H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6',overview:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',marketplace:'M3 7h18l-2 5H5L3 3H1M6 16h13M7 20h.01M18 20h.01',assistant:'M4 5h16v12H9l-5 4zM8 9h8M8 13h5',resources:'M7 8V5h10v3M5 8h14v11H5zM9 12h.01M15 12h.01M9 16h6',customers:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M14 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',deployments:'M8 6V3h8v3M3 6h18v15H3zM3 12h18M10 12v3h4v-3',runs:'m8 4 12 8-12 8zM3 4v16',reports:'M4 20V10M10 20V4M16 20v-7M22 20H1',incidents:'M12 3 1 21h22zM12 9v5M12 18h.01',support:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M9.5 8a2.7 2.7 0 1 1 4.5 2c-1.5 1-2 1.4-2 3M12 17h.01',settings:'M4 6h5m4 0h7M4 12h9m4 0h3M4 18h3m4 0h9M13 6a2 2 0 1 1-4 0 2 2 0 0 1 4 0M17 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0M11 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',profile:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',back:'M19 12H5m6-6-6 6 6 6',agent:'M12 3v3M4 8h16v12H4zM8 12h.01M16 12h.01M8 16h8M1 11v6M23 11v6M10 3h4',robot:'M8 2h8v5H8zM6 9h12v8H6zM4 10 2 17M20 10l2 7M9 17v5M15 17v5M10 12h4',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',refresh:'M20 8a9 9 0 1 0 1 7M20 2v6h-6'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.resources}"/></svg>`}function badge(s){return `<span class="badge ${e(s)}">${e(s)}</span>`}
let state,workspaces=[],workspace=localStorage.getItem('opennoir-workspace')||'northstar',customer='',filter='all',search='',teamStatus='all',loadVersion=0;
const lookup=(kind,id)=>state[kind].find(x=>x.id===id);const cname=id=>lookup('customers',id)?.name||'Workspace';const rname=id=>lookup('resources',id)?.name||'Unknown';
function goto(route){if(customer&&['marketplace','assistant','profile','guide'].includes(route.split('/')[0])){customer='';location.hash=route;load();return}location.hash=route}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function api(path,body){let res=await fetch('/api/'+path,{headers:{'Content-Type':'application/json','X-Workspace-Id':workspace},...(body?{method:'POST',body:JSON.stringify(body)}:{})});let data=await res.json();if(!res.ok){let err=Error(data.error||'Request failed');err.status=res.status;throw err}return data}
async function load(){let version=++loadVersion;try{let [s,review,listings]=await Promise.all([api('state'+(customer?'?customer='+encodeURIComponent(customer):'')),api('feedback'),api('catalog')]);if(version!==loadVersion)return;state=s;reviewComments=review.comments;catalogData=listings;render()}catch(err){$('#content').innerHTML=`<section class="panel"><h1>Connection needs attention.</h1><p>${e(err.message)}</p><button class="primary" data-action="reload">Try again</button></section>`}}
async function cmd(data){let result=await api('commands'+(customer?'?customer='+encodeURIComponent(customer):''),{...data,revision:state.revision});await load();return result.result}
function heading(title,sub,action=''){return `<div class="eyebrow">${e(state.workspace)}</div><div class="heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}function empty(s){return `<div class="empty">${s}</div>`}
let characterMotion=localStorage.getItem('opennoir-character-motion')!=='off'&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
function motionToggle(){let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;return `<button class="pill motion-toggle" data-action="toggle-motion" aria-pressed="${characterMotion&&!reduced}" ${reduced?'disabled':''}>${reduced?'Reduced motion':characterMotion?'Pause motion':'Enable motion'}</button>`}
function resourceArt(r,small=false){let file=r.type==='robot'?'robot-studio':r.capabilities.includes('analysis')?'agent-sage':'agent-nova';let img=`<img class="resource-art ${r.type} ${small?'thumbnail':''}" src="assets/${file}.png" alt="${e(r.name)} ${r.type==='robot'?'realistic humanoid robot concept':'abstract AI agent mascot'}" ${small?'':'loading="lazy"'}>`;if(small)return img;return `<button class="art-interactive ${r.type}" data-greet="${r.id}" aria-label="Say hello to ${e(r.name)}"><span class="art-idle"><span class="art-tilt">${img}</span></span><span class="art-floor" aria-hidden="true"></span><span class="art-bubble" aria-hidden="true">${r.status==='maintenance'?'Resting. Back soon!':'Hello, I’m '+e(r.name)+'!'}</span><span class="art-hint" aria-hidden="true">Tap to say hello</span></button>`}
function resourceName(r){return `<div class="resource-name"><span class="resource-icon ${r.type}">${resourceArt(r,true)}</span><div><div class="cell-main">${e(r.name)}</div><div class="cell-sub">${e(r.model)} · ${r.type==='agent'?'AI agent':'Robot'}</div></div></div>`}
function metric(label,value,note,ico){return `<div class="stat"><div class="stat-top">${label}${icon(ico)}</div><div class="metric">${value}</div><div class="muted">${note}</div></div>`}
const cardLabels={reports:'Usage & costs',resources:'My team',deployments:'Marketplace',support:'Report issue'};
const backgroundNames={earnings:'Prism',fleet:'Soft sage',market:'Golden blur',support:'Color spectrum'};
const gradientPresets=[
 ['Dawn','#f9d7c8','#e9d4e8','#bdcdeb'],['Glacier','#d7ecee','#c4d8ee','#dcd5ed'],['Sage','#e9ebd7','#cbdacc','#b7d5d0'],['Apricot','#f7dfc3','#f4c9bc','#edc7d4'],
 ['Iris','#e2dcf5','#bec8ed','#c5e5ea'],['Sand','#f1e9d9','#e0d6c6','#ced7cd'],['Rose','#f7dce3','#e7c2d4','#d7c6e8'],['Lagoon','#d2ede5','#a5d2d2','#a9c5e3'],
 ['Aurora','#6274b9','#ad8cc5','#e9b4bd'],['Ember','#d49a89','#c57d7c','#8376a6'],['Midnight','#182941','#344b65','#6d668b'],['Graphite','#dce0e5','#aab4c2','#8291a3']
];
const defaultCards=()=>Object.fromEntries(Object.keys(cardLabels).map((k,i)=>[k,{image:['earnings','fleet','market','support'][i],mode:'image',colors:gradientPresets[i].slice(1),angle:120,shape:'linear',overlay:61,saturation:100,hue:0,blur:0}]));
let cardDraft=null,editingCard='reports';
function gradientCSS(c){return c.shape==='radial'?`radial-gradient(ellipse at 20% 15%,${c.colors.join(',')})`:`linear-gradient(${c.angle}deg,${c.colors.join(',')})`}
function cardStyle(c){let gradient=c.mode==='gradient',colors=c.colors||['#ffffff','#ffffff','#ffffff'];let luminance=colors.reduce((n,hex)=>n+(parseInt(hex.slice(1,3),16)*.2126+parseInt(hex.slice(3,5),16)*.7152+parseInt(hex.slice(5,7),16)*.0722),0)/3;let ink=gradient&&luminance<135&&c.overlay<35?'#ffffff':'#1b2430';return `--card-overlay:${c.overlay/100};--card-saturation:${c.saturation/100};--card-hue:${c.hue}deg;--card-blur:${c.blur}px;--card-ink:${ink};${gradient?'background-image:'+gradientCSS(c):''}`}
function quickCard(key,label){let c=state.settings.cards?.[key]||defaultCards()[key];return `<button class="quick ${c.mode==='gradient'?'custom-gradient':''}" style="${cardStyle(c)}" data-go="${key==='deployments'?'marketplace':key}">${c.mode==='gradient'?'':`<img src="assets/${c.image}.jpg" alt="">`}${icon(key==='deployments'?'marketplace':key)}<span>${label}</span></button>`}
function appearance(key='reports'){if(customer)return toast('Switch to all customers to customize workspace cards.');let defaults=defaultCards();cardDraft=Object.fromEntries(Object.keys(cardLabels).map(k=>[k,{...defaults[k],...structuredClone(state.settings.cards?.[k]||{})}]));editingCard=key;if(cardDraft[key].mode!=='gradient'){cardDraft[key].mode='gradient';cardDraft[key].overlay=0}showAppearance()}
function gradientBuilder(c){return `<div class="gradient-presets" role="group" aria-label="Gradient presets">${gradientPresets.map(([name,...colors],i)=>`<button type="button" class="gradient-preset" data-gradient="${i}" aria-label="${name} gradient"><span style="background:linear-gradient(120deg,${colors.join(',')})"></span>${name}</button>`).join('')}</div><div class="builder-heading"><h3>Or build your own</h3><button type="button" class="link" data-action="scratch-gradient">Start from scratch</button></div><div class="color-stops">${c.colors.map((hex,i)=>`<div><label for="gradient-color-${i}">Color ${i+1}</label><div class="color-input"><input type="color" id="gradient-color-${i}" data-color="${i}" value="${hex}"><input aria-label="Color ${i+1} hex" class="hex-input" data-hex="${i}" value="${hex}" maxlength="7" pattern="#[0-9a-fA-F]{6}" required></div></div>`).join('')}</div><div class="appearance-controls"><div><label for="gradient-shape">Blend</label><select id="gradient-shape"><option value="linear" ${c.shape==='linear'?'selected':''}>Linear</option><option value="radial" ${c.shape==='radial'?'selected':''}>Radial</option></select></div><div><label for="gradient-angle">Direction <output id="angle-output">${c.angle}°</output></label><input type="range" id="gradient-angle" min="0" max="360" value="${c.angle}" ${c.shape==='radial'?'disabled':''}></div></div>`}
function showAppearance(){let c=cardDraft[editingCard];let body=`<form data-form="appearance"><p>Pick a card. Choose any gradient below, or create one from your own colors.</p><label for="editing-card">Card to customize</label><select id="editing-card">${Object.entries(cardLabels).map(([k,t])=>`<option value="${k}" ${k===editingCard?'selected':''}>${t}</option>`).join('')}</select><div class="quick appearance-preview ${c.mode==='gradient'?'custom-gradient':''}" id="appearance-preview" style="${cardStyle(c)}">${c.mode==='gradient'?'':`<img src="assets/${c.image}.jpg" alt="Selected blurry gradient background">`}${icon(editingCard)}<span>${cardLabels[editingCard]}</span></div><div class="background-modes" role="group" aria-label="Background type"><button type="button" class="pill ${c.mode==='gradient'?'selected':''}" data-backgroundmode="gradient">Create a gradient</button><button type="button" class="pill ${c.mode!=='gradient'?'selected':''}" data-backgroundmode="image">Image backgrounds</button></div>${c.mode==='gradient'?gradientBuilder(c):`<fieldset class="background-choices"><legend>Choose gradient image</legend>${Object.entries(backgroundNames).map(([key,name])=>`<label class="background-choice"><input type="radio" name="background" value="${key}" ${c.image===key?'checked':''}><img src="assets/${key}.jpg" alt=""><span>${name}</span></label>`).join('')}</fieldset><div class="appearance-controls">${[['saturation','Color intensity',0,150,'%'],['hue','Color shift',0,360,'°'],['blur','Softness',0,10,'px']].map(([key,label,min,max,unit])=>`<div><label for="card-${key}">${label}<output id="output-${key}">${c[key]}${unit}</output></label><input type="range" id="card-${key}" data-adjust="${key}" min="${min}" max="${max}" value="${c[key]}" data-unit="${unit}"></div>`).join('')}</div>`}<label for="card-overlay">Light overlay <output id="output-overlay">${c.overlay}%</output></label><input type="range" id="card-overlay" data-adjust="overlay" min="0" max="85" value="${c.overlay}" data-unit="%"><div class="error" id="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="link" data-action="reset-card">Reset card</button><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary">Save all four cards</button></div></form>`;if($('#dialog').open){$('#dialog').innerHTML=`<div class="modal-head"><h2 id="dialog-title">Choose your gradients.</h2><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`}else modal('Choose your gradients.',body)}
function previewAppearance(){let c=cardDraft[editingCard],p=$('#appearance-preview');p.setAttribute('style',cardStyle(c));p.classList.toggle('custom-gradient',c.mode==='gradient');let img=p.querySelector('img');if(img)img.src='assets/'+c.image+'.jpg'}
function overview(){let active=state.deployments.filter(x=>x.status==='active').length,open=state.incidents.filter(x=>x.status==='open').length,cost=state.runs.reduce((n,r)=>n+r.cost,0),succeeded=state.runs.filter(x=>x.status==='succeeded').length;return heading('One place. Every operation.','Manage your agents, robots, and customer services with a little more clarity.','<button class="primary" data-action="new-deployment">'+icon('plus')+' Create work</button>')+`<div class="stats">${metric('Managed resources',String(state.resources.length).padStart(2,'0'),state.resources.filter(x=>x.type==='agent').length+' AI agents · '+state.resources.filter(x=>x.type==='robot').length+' robots','resources')}${metric('Active deployments',String(active).padStart(2,'0'),state.customers.length+' customer accounts in view','deployments')}${metric('Recorded execution cost',cash(cost),succeeded+' successful runs · mock rates','reports')}${metric('Needs attention',String(open).padStart(2,'0'),'Open operational incidents','incidents')}</div><div class="appearance-toolbar"><span class="muted">QUICK ACTIONS</span><span class="muted">Personalize in Settings</span></div><div class="actions">${Object.entries(cardLabels).map(([key,label])=>quickCard(key,label)).join('')}</div><div class="grid"><section class="panel"><div class="panel-head"><h2>Your operations</h2><button class="link" data-go="resources">View inventory</button></div>${resourceTable(state.resources.slice(0,5))}</section><section class="panel"><div class="panel-head"><h2>On your radar</h2><span class="eyebrow">LIVE RECORDS</span></div>${state.incidents.filter(x=>x.status==='open').slice(0,2).map(i=>`<div class="activity"><span class="event-dot"></span><div><h3>${e(i.title)}</h3><p>${e(rname(i.resourceId))} · ${i.kind==='maintenance'?'Service required':'Execution issue'}</p><button class="link" data-go="incidents" style="margin-top:10px">Review incident</button></div></div>`).join('')||'<p>No unresolved incidents in this view.</p>'}<div class="notice">Local control plane, real saved records.<br>Execution and telemetry use the mock connector.</div><button class="link" data-go="settings">View connector status</button></section></div><section class="panel section"><div class="panel-head"><h2>Recent runs</h2><button class="link" data-go="runs">All runs</button></div>${runTable(state.runs.slice(0,4))}</section>`}
function resourceTable(rs){return rs.length?`<div class="table-wrap"><table><thead><tr><th>RESOURCE</th><th>STATUS</th><th>HEALTH</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${resourceName(r)}</td><td>${badge(r.status)}</td><td>${r.health}%<div class="healthbar ${r.health<60?'low':''}"><i style="width:${r.health}%"></i></div></td><td><button class="link" data-go="resource/${r.id}">Details</button></td></tr>`).join('')}</tbody></table></div>`:empty('No resources in this customer scope.')}
function resources(){let rs=state.resources.filter(r=>(filter==='all'||r.type===filter)&&(teamStatus==='all'||r.status===teamStatus)&&`${r.name} ${r.model} ${r.capabilities.join(' ')}`.toLowerCase().includes(search.toLowerCase()));return heading('My team','Robots and AI agents you manage, all in one place.',!customer?'<button class="primary" data-action="add-resource">Add</button>':'')+`<div class="toolbar">${['all','agent','robot'].map(f=>`<button class="pill ${filter===f?'selected':''}" data-filter="${f}">${f==='all'?'All resources':f==='agent'?'AI agents':'Robots'}</button>`).join('')}<select id="team-status" aria-label="Filter team status">${[['all','All statuses'],['available','Available'],['deployed','Working'],['reserved','Paused / reserved'],['maintenance','Needs attention']].map(([v,t])=>`<option value="${v}" ${teamStatus===v?'selected':''}>${t}</option>`).join('')}</select><input id="search" aria-label="Search resources" placeholder="Search names or capabilities" value="${e(search)}"></div><div class="cards">${rs.map(r=>`<article class="panel resource-card"><div class="card-top">${badge(r.status)}<span class="eyebrow">${r.type==='agent'?'DIGITAL':'PHYSICAL'}</span></div><div class="resource-visual">${resourceArt(r)}</div><h2>${e(r.name)}</h2><p>${e(r.model)}</p><code class="opennoir-id">${e(r.publicId||r.id)}</code><div class="chips">${r.capabilities.map(c=>`<span class="chip">${e(c)}</span>`).join('')}</div><div class="specs"><div><strong>${r.health}%</strong><span>Health</span></div><div><strong>${r.type==='robot'?r.battery+'%':'Mock'}</strong><span>${r.type==='robot'?'Battery':'Connector'}</span></div><div><strong>${cash(r.rate)}</strong><span>Reference / day</span></div></div><button class="secondary full" data-go="resource/${r.id}">View resource</button></article>`).join('')||empty('No matching resources.')}</div>`}
function resourceDetail(id){let r=lookup('resources',id);if(!r)return empty('Resource not found in this scope.');let ds=state.deployments.filter(d=>d.resourceId===id);return `<div class="resource-detail-toolbar">${backButton('resources','Back to resources')}</div><div class="resource-header"><span class="resource-icon ${r.type}">${resourceArt(r,true)}</span><div><div class="eyebrow">${r.type==='agent'?'AI AGENT':'PHYSICAL ROBOT'} / MOCK CONNECTOR</div><h1>${e(r.name)}</h1><p>${e(r.model)}</p><code class="opennoir-id">${e(r.publicId||r.id)}</code></div></div><div class="split section"><section class="panel"><div class="panel-head"><h2>Resource health</h2>${badge(r.status)}</div><div class="detail-visual">${resourceArt(r)}</div><div class="specs"><div><strong>${r.health}%</strong><span>Health score</span></div><div><strong>${r.type==='robot'?r.battery+'%':'Local'}</strong><span>${r.type==='robot'?'Battery':'Runtime'}</span></div><div><strong>Mock</strong><span>Telemetry source</span></div></div><div class="row"><span>Last reported</span><strong>${date(r.lastSeen)}</strong></div><div class="chips">${r.capabilities.map(c=>`<span class="chip">${e(c)}</span>`).join('')}</div><p>Health, battery, and service status are local mock values. No physical device is connected.</p></section><section class="panel customer-deployments"><h2>Connected assignments</h2>${ds.map(d=>`<div class="row"><div><strong>${d.confidential?'◈ Confidential deployment':e(d.name)}</strong><p>${d.confidential?'Private client':e(cname(d.customerId))}</p></div>${badge(d.status)}</div>`).join('')||'<p>This resource has not been deployed.</p>'}${r.status==='available'?'<button class="primary section" data-action="new-deployment">Create assignment</button>':''}</section></div><section class="panel section"><div class="panel-head"><h2>Run history</h2><button class="link" data-go="runs">All runs</button></div>${runTable(state.runs.filter(x=>x.resourceId===id))}</section>`}
function customers(){return heading('People & businesses','Connect the people you serve by their opennoir ID.',!customer?'<button class="primary" data-action="connect-person">Connect by ID</button>':'')+`<div class="notice soft">These are your service connections—not a second account system. Connect a person or business when you want to assign a robot or agent to work for them. You can manage your own resources without adding anyone.</div><div class="cards">${state.customers.map(c=>`<article class="panel customer-card"><div class="card-top"><span class="resource-icon">${icon('customers')}</span><span class="badge">${c.type}</span></div><h2>${e(c.name)}</h2><p>${e(c.contact)}</p><code class="opennoir-id">${e(c.publicId||c.id)}</code><div class="row"><span>Assignments</span><span>${state.deployments.filter(x=>x.customerId===c.id&&x.status!=='ended').length}</span></div><div class="row"><span>Service plan</span><span>${e(c.plan)}</span></div><div class="row"><span>Modeled service value</span><span>${cash(state.runs.filter(x=>x.customerId===c.id).reduce((n,x)=>n+x.charge,0))}</span></div><button class="secondary full section" data-scope="${c.id}">View connected activity</button></article>`).join('')}</div>`}
function backButton(page,label){return `<button class="back-button" data-go="${page}">${icon('back')}<span>${label}</span></button>`}
function deploymentActions(d){return `<div class="card-actions">${d.status==='draft'||d.status==='paused'?`<button class="primary" data-transition="active" data-id="${d.id}">Activate</button>`:''}${d.status==='active'?`<button class="primary" data-newrun="${d.id}">New run</button><button class="secondary" data-transition="paused" data-id="${d.id}">Pause</button>`:''}${d.status!=='ended'?`<button class="danger" data-enddeployment="${d.id}">End</button>`:''}</div>`}
function assignmentCards(){return heading('Your work','Manage ongoing work and the team member assigned to it.','<button class="primary" data-action="new-deployment">Create work</button>')+`<div class="cards">${state.deployments.filter(d=>workTab==='paused'?d.status==='paused':workTab==='completed'?d.status==='ended':['active','draft'].includes(d.status)).map(d=>`<article class="panel deployment-card"><div class="card-top">${badge(d.status)}<span class="muted">${e(rname(d.resourceId))}</span></div><h2 style="margin-top:25px">${d.confidential?'◈ Confidential deployment':e(d.name)}</h2><p>${d.confidential?'Private client':e(cname(d.customerId))}</p><div class="row"><span>Capability</span><strong>${d.confidential?'Protected':e(d.capability)}</strong></div><div class="row"><span>Created</span><strong>${date(d.createdAt)}</strong></div><div class="row"><span>Run records</span><strong>${state.runs.filter(r=>r.deploymentId===d.id).length}</strong></div><p class="small deployment-note">${d.confidential?'Deployment details are masked in the console. Metadata remains in the local API.':'Assigned service remains under operator control. Pause or end it when the work changes.'}</p>${deploymentActions(d)}<button class="secondary full" data-workview="${d.id}">View work</button></article>`).join('')||empty('No deployments yet. Create one to reserve an available resource.')}</div>`}
function runTable(rs){return rs.length?`<div class="table-wrap"><table><thead><tr><th>RUN</th><th>RESOURCE / CUSTOMER</th><th>STATUS</th><th>COST</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td><span class="cell-main">${lookup('deployments',r.deploymentId)?.confidential?'Confidential task':e(r.name)}</span><div class="cell-sub">Attempt ${r.attempt} · ${date(r.createdAt)}</div></td><td>${e(rname(r.resourceId))}<div class="cell-sub">${lookup('deployments',r.deploymentId)?.confidential?'Private client':e(cname(r.customerId))}</div></td><td>${badge(r.status)}</td><td>${cash(r.cost)}</td><td><button class="link" data-go="run/${r.id}">Inspect</button></td></tr>`).join('')}</tbody></table></div>`:empty('No run records in this view.')}
function runs(){return heading('Activity','A run is one attempt to complete a task—for example, inspect an aisle or process a batch of documents.','<button class="primary" data-action="new-run">Queue run</button>')+`<div class="notice soft"><strong>Assignment = the ongoing service.</strong> A run = one task attempt within that service. Each attempt records whether it completed, failed, or was cancelled.</div><section class="panel">${runTable(state.runs)}</section><div class="notice">Runs advance only through explicit mock actions. No scheduler, inference provider, or robot is executing in the background.</div>`}
function runDetail(id){let r=lookup('runs',id);if(!r)return empty('Run not found in this scope.');return `${backButton('runs','Back to runs')}`+heading(lookup('deployments',r.deploymentId)?.confidential?'Confidential task':e(r.name),'Run events are stored with the workspace in SQLite.',badge(r.status))+`<div class="split"><section class="panel"><h2>Execution record</h2><div class="row"><span>Resource</span><strong>${e(rname(r.resourceId))}</strong></div><div class="row"><span>Customer</span><strong>${lookup('deployments',r.deploymentId)?.confidential?'Private client':e(cname(r.customerId))}</strong></div><div class="row"><span>Attempt</span><strong>${r.attempt}</strong></div><div class="row"><span>Completed units</span><strong>${r.units}</strong></div><div class="row"><span>Execution cost / service value</span><strong>${cash(r.cost)} / ${cash(r.charge)}</strong></div><div class="card-actions">${r.status==='queued'?`<button class="primary" data-runstatus="running" data-id="${r.id}">Start mock run</button>`:''}${r.status==='running'?`<button class="primary" data-runstatus="succeeded" data-id="${r.id}">Complete successfully</button><button class="danger" data-runstatus="failed" data-id="${r.id}">Simulate failure</button>`:''}${r.status==='failed'?`<button class="primary" data-runstatus="retry" data-id="${r.id}">Retry run</button>`:''}${['queued','running'].includes(r.status)?`<button class="secondary" data-runstatus="cancelled" data-id="${r.id}">Cancel run</button>`:''}</div></section><section class="panel"><h2>Event timeline</h2><div class="timeline">${r.events.map(x=>`<div class="activity"><span class="event-dot"></span><div><p>${e(x.message)}</p><time>${date(x.at)}${x.code?' · '+e(x.code):''}</time></div></div>`).join('')}</div></section></div>`}
function reports(){let cost=state.runs.reduce((n,r)=>n+r.cost,0),charge=state.runs.reduce((n,r)=>n+r.charge,0),success=state.runs.filter(x=>x.status==='succeeded').length,finished=state.runs.filter(x=>['succeeded','failed'].includes(x.status)).length;return heading('Clarity, without the spreadsheet.','Recorded usage and modeled service economics across your customers.','<button class="secondary" data-action="export">Export CSV</button>')+`<div class="stats">${metric('Modeled service value',cash(charge),'Mock rate card · not invoiced','reports')}${metric('Execution cost',cash(cost),'Recorded mock usage costs','reports')}${metric('Contribution',cash(charge-cost),'Service value minus execution cost','reports')}${metric('Run success',finished?Math.round(success/finished*100)+'%':'—',finished+' terminal runs · current attempt','runs')}</div><div class="grid"><section class="panel"><div class="panel-head"><h2>Customer service breakdown</h2><span class="muted">All recorded time</span></div><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>RUNS</th><th>COST</th><th>SERVICE VALUE</th></tr></thead><tbody>${state.customers.map(c=>{let rs=state.runs.filter(x=>x.customerId===c.id);return `<tr><td>${e(c.name)}</td><td>${rs.length}</td><td>${cash(rs.reduce((n,x)=>n+x.cost,0))}</td><td>${cash(rs.reduce((n,x)=>n+x.charge,0))}</td></tr>`}).join('')}</tbody></table></div></section><section class="panel"><h2>Service economics</h2><div class="costbar"><span style="width:${charge?cost/charge*100:0}%"></span><span style="flex:1"></span></div><div class="row"><span>Execution cost</span><strong>${cash(cost)}</strong></div><div class="row"><span>Contribution</span><strong>${cash(charge-cost)}</strong></div><p>These are mock estimates, not revenue or invoices. Hardware purchase costs, staff time, taxes, depreciation, and maintenance costs are excluded. Units differ between agents (tokens) and robots (items); they are not summed together.</p></section></div>`}
let incidentStatus='all',incidentSeverity='all';
function incidents(){let issues=state.incidents.filter(i=>(incidentStatus==='all'||i.status===incidentStatus)&&(incidentSeverity==='all'||i.severity===incidentSeverity));return backButton('overview','Back to overview')+heading('Incidents & maintenance','Review issues, understand their priority, and follow the next step.')+`<div class="toolbar"><label class="filter-label" for="incident-status">Status</label><select id="incident-status">${['all','open','resolved'].map(v=>`<option value="${v}" ${v===incidentStatus?'selected':''}>${v==='all'?'All statuses':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><label class="filter-label" for="incident-severity">Priority</label><select id="incident-severity">${['all','high','medium','low'].map(v=>`<option value="${v}" ${v===incidentSeverity?'selected':''}>${v==='all'?'All priorities':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><span class="muted">${issues.length} ${issues.length===1?'issue':'issues'}</span></div><div class="cards">${issues.map(i=>`<article class="panel incident-card"><div class="card-top"><button data-incidentstatus="${i.status}" aria-label="Filter ${i.status} incidents">${badge(i.status)}</button><button data-incidentseverity="${i.severity}" aria-label="Filter ${i.severity} priority">${badge(i.severity)}</button></div><h2>${e(i.title)}</h2><p>${e(rname(i.resourceId))} · ${e(cname(i.customerId))}</p><div class="chips"><span class="chip">${e(i.kind)}</span><span class="chip">${date(i.createdAt)}</span></div><p>${i.status==='resolved'?'Resolved. Review the recorded action and the resource’s next step.':i.kind==='maintenance'?'Resource is held out of work until the service check is complete.':'Execution needs review. Check the failure context before retrying.'}</p><div class="incident-card-actions"><button class="secondary" data-incidentdetails="${i.id}">View issue details</button><button class="${i.status==='open'?'primary':'secondary'}" data-incidentassistant="${i.id}">${i.status==='open'?'Resolve with assistant':'Review with assistant'}</button></div></article>`).join('')||empty('No issues match these filters.')}</div><div class="notice">The opennoir assistant below is a scripted local guide. It can simulate checks and save a confirmed resolution; it cannot inspect or repair a physical robot.</div>`}
function incidentDetails(id){let i=lookup('incidents',id);modal('Issue details',`<h3>${e(i.title)}</h3><p>${e(rname(i.resourceId))} · ${e(cname(i.customerId))}</p><div class="row"><span>Status</span>${badge(i.status)}</div><div class="row"><span>Priority</span>${badge(i.severity)}</div><p>${i.severity==='high'?'High priority: service is blocked and a safety or hardware check is required.':i.severity==='medium'?'Medium priority: a run failed and needs review before retrying.':'Low priority: review the issue before the next scheduled work.'}</p><h3 class="section">Recorded history</h3><div class="timeline">${i.events.map(ev=>`<div class="activity"><div><p>${e(ev.message)}</p><time>${date(ev.at)}</time></div></div>`).join('')}</div><div class="modal-actions"><button class="secondary" data-action="close">Close</button><button class="primary" data-incidentassistant="${i.id}">Open assistant</button></div>`)}
let assistantIncidentId=null,assistantStage='intro',assistantReply='';
function incidentAssistant(id,stage='intro'){assistantIncidentId=id;assistantStage=stage;assistantReply='';drawIncidentAssistant()}
function drawIncidentAssistant(){let i=lookup('incidents',assistantIncidentId);if(!i)return;let maintenance=i.kind==='maintenance',resolved=i.status==='resolved';let intro=resolved?'This issue is already resolved. You can review its history and check the deployment before resuming work.':maintenance?'The resource is paused for a service check. I can guide you through a simulated diagnostic and verification.':'A run needs attention. I can guide you through a simulated provider-health check before you retry.';let diagnosis=maintenance?'Mock diagnostics: the actuator check requires service. The next demo step simulates service followed by a passing verification.':'Mock diagnostics: the provider timed out. The next demo step simulates restored provider health.';modal('opennoir assistant',`<div class="assistant-label">Scripted demo · no live AI or hardware connection</div><h3 class="section">${e(i.title)}</h3><div class="assistant-message">${intro}</div>${assistantStage!=='intro'?`<div class="assistant-message">${diagnosis}</div>`:''}${assistantStage==='verified'?'<div class="assistant-message verified">Simulated verification passed. Confirm below to save the resolution. Deployment resumption stays under your control.</div>':''}${assistantReply?`<div class="assistant-message">${e(assistantReply)}</div>`:''}<div class="assistant-prompts"><button data-incidentquestion="cause">What happened?</button><button data-incidentquestion="priority">Why this priority?</button><button data-incidentquestion="next">What happens next?</button></div><div class="modal-actions"><button class="secondary" data-action="close">Close</button>${!resolved?(assistantStage==='intro'?'<button class="primary" data-assistantstage="diagnosed">Run simulated diagnostics</button>':assistantStage==='diagnosed'?`<button class="primary" data-assistantstage="verified">${maintenance?'Simulate service & verify':'Simulate provider recovery'}</button>`:'<button class="primary" data-confirmassistant="true">Confirm simulated resolution</button>'):''}</div>`)}
function profile(){return heading('Operator profile','Your local operator identity and workspace context.')+`<div class="split"><section class="panel"><span class="profile-mark">${icon('profile')}</span><h2>${e(state.settings.operatorName||'Workspace operator')}</h2><p>${e(state.name)} · ${e(state.workspace)}</p><label>Your opennoir ID</label><code class="identity-large">${e(state.identity?.publicId||'Pending')}</code><p>Your ID identifies this local demo profile. Public sign-in is not connected.</p><button class="secondary section" data-go="guide">How opennoir works</button><form data-form="operator"><label for="operator-name">Display name</label><input id="operator-name" name="operatorName" value="${e(state.settings.operatorName||'Workspace operator')}" required maxlength="120"><p>This local display name is not a sign-in or permission setting.</p><button class="primary section" ${customer?'disabled':''}>Save profile</button></form></section><section class="panel"><h2>Security & sign-in</h2><p>Public sign-in and account recovery are not connected. Your opennoir ID identifies a local demo profile; it does not authenticate access.</p><h2>Workspace preferences</h2><p>Card gradients, operating region, organization identity, and notifications are in Settings.</p><button class="secondary section" data-go="settings">Open Settings</button></section></div>`}
function settings(){return heading('A foundation you can own.','Open source. Local data. Explicit integration boundaries.')+`<section class="panel appearance-settings"><div class="panel-head"><h2>Card gradients</h2><span class="muted">Choose each one yourself</span></div><p>Click a card below to pick a preset or build your own gradient. Save when you’re happy with your choices.</p><div class="actions">${Object.entries(cardLabels).map(([key,label])=>quickCard(key,label).replace(`data-go="${key==='deployments'?'marketplace':key}"`,`data-editcard="${key}" aria-label="Choose gradient for ${label}"`)).join('')}</div>${customer?'<p>Switch Customer scope to All customers to edit these workspace settings.</p>':'<p class="small">Your choices apply to this organization. Nothing changes until you press Save all four cards.</p>'}</section><div class="split section"><section class="panel"><h2>Your workspace</h2><p>Switch the sample workspace here. People filters limit operational activity; design feedback still shows all pages.</p><label for="workspace">Workspace</label><select id="workspace">${workspaces.map(w=>`<option value="${w.id}" ${w.id===workspace?'selected':''}>${e(w.name)}</option>`).join('')}</select><label for="customer">Activity filter</label><select id="customer"><option value="">Everyone</option>${state.customers.map(c=>`<option value="${c.id}" ${c.id===customer?'selected':''}>${e(c.name)}</option>`).join('')}</select><button class="secondary section" data-go="guide">Understand the app</button></section><section class="panel"><h2>Workspace settings</h2><div class="row"><span>Character motion</span>${motionToggle()}</div><div class="row"><span>Organization</span><strong>${e(state.name)}</strong></div><div class="row"><span>Operating region</span><strong>${e(state.settings.region)}</strong></div><div class="row"><span>Currency</span><strong>USD</strong></div><form id="settings-form"><label for="org-name">Organization name</label><input id="org-name" name="name" required maxlength="120" value="${e(state.name)}" ${customer?'disabled':''}><label for="workspace-name">Workspace name</label><input id="workspace-name" name="workspace" required maxlength="120" value="${e(state.workspace)}" ${customer?'disabled':''}><label for="region">Operating region</label><input id="region" name="region" required maxlength="120" value="${e(state.settings.region)}" ${customer?'disabled':''}><label class="check"><input type="checkbox" name="notifications" ${state.settings.notifications?'checked':''}>Show completion notifications</label><p>Applies to successful run completion notices in this console.</p><button class="secondary section" ${customer?'disabled':''}>Save preference</button></form></section><section class="panel"><div class="panel-head"><h2>Connector status</h2><span class="badge">Mock only</span></div><div class="row"><span>Local mock adapter</span><strong>Available</strong></div><div class="row"><span>AI providers</span><strong>Not connected</strong></div><div class="row"><span>Physical devices</span><strong>Not connected</strong></div><p>Implement the adapter contract to integrate your own execution system. This release does not send remote commands.</p><div class="notice">SQLite saves real application data. The mock connector simulates outcomes, usage, and telemetry.</div></section><section class="panel"><h2>Operator access</h2><p>This is a single trusted-operator installation bound to localhost. Workspace and customer selectors provide context, not authorization. Do not expose this service to the internet without adding authentication and authorization.</p><div class="row"><span>License</span><strong>MIT</strong></div><div class="row"><span>Release</span><strong>0.3.0 · Work & earnings preview</strong></div></section><section class="panel"><h2>Workspace activity</h2>${state.events.slice(0,5).map(ev=>`<div class="activity"><span class="event-dot"></span><div><p>${e(ev.message)}</p><time>${date(ev.at)}</time></div></div>`).join('')||'<p>Activity is visible in the all-customers context.</p>'}</section></div>`}
const pageLabels={overview:'Home',marketplace:'Marketplace',resources:'My team',customers:'People & businesses',deployments:'Work',runs:'Activity',reports:'Reports',earnings:'Earnings',incidents:'Issues & maintenance',support:'Help & support',assistant:'Assistant',settings:'Settings',profile:'My account',guide:'How opennoir works'};
function render(){document.body.classList.toggle('character-motion',characterMotion);let [page='overview',id]=location.hash.slice(1).split('/');if(!page)page='overview';let active=page==='resource'?'resources':page==='run'?'runs':page;$('#nav').innerHTML=`<button class="mark" data-go="overview" aria-label="opennoir overview">◉</button><nav class="navlinks">${['overview','marketplace','resources','customers','deployments','earnings','runs','reports','incidents'].map(p=>`<button class="navbtn ${active===p?'active':''}" data-go="${p}" aria-label="${pageLabels[p]||p}" ${active===p?'aria-current="page"':''}>${icon(p)}</button>`).join('')}</nav><div class="navbottom">${['assistant','support','settings','profile'].map(p=>`<button class="navbtn ${active===p?'active':''}" data-go="${p}" aria-label="${pageLabels[p]}">${icon(p)}</button>`).join('')}</div>`;$('#context').innerHTML=`<div class="workspace-brand"><button class="wordmark" data-go="overview">opennoir</button><span>${e(state.name)}</span></div><div class="header-actions">${customer?`<button class="scope-chip" data-action="clear-scope">${e(cname(customer))} · Clear filter ×</button>`:''}<button class="header-button" data-action="notifications" aria-label="Notifications">${icon('notifications')}<span>Notifications</span></button><button class="header-button" data-go="marketplace">${icon('marketplace')}<span>Marketplace</span></button><button class="header-button" data-go="profile">${icon('profile')}<span>My account</span></button></div>`;$('#content').innerHTML=({overview,resources,resource:()=>resourceDetail(id),customers,deployments,runs,run:()=>runDetail(id),reports,earnings,incidents,support,settings:()=>settings()+financeSettings(),profile,marketplace,assistant,guide}[page]||overview)();document.title=(pageLabels[active]||'opennoir')+' — opennoir';feedback?.update();let chat=$('.assistant-chat-log');if(chat)chat.scrollTop=chat.scrollHeight}
function modal(title,body){$('#dialog').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;$('#dialog').setAttribute('aria-labelledby','dialog-title');$('#dialog').showModal()}
const input=(name,label,placeholder='')=>`<label for="${name}">${label}</label><input name="${name}" id="${name}" required maxlength="120" placeholder="${placeholder}">`;
const footer=label=>`<div class="error" id="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary">${label}</button></div>`;
function openCustomer(){modal('A new customer relationship.',`<form data-form="customer">${input('name','Customer name','Company or individual')}<label for="type">Account type</label><select id="type" name="type"><option>Business</option><option>Individual</option></select>${input('contact','Contact reference','operations@example.com')}<p>Stored locally. No email will be sent.</p>${footer('Create customer')}</form>`)}
function openResource(selectedType='agent'){if(customer)return toast('Switch to all customers to register resources.');modal('Add capability to your team.',`<form data-form="resource">${input('name','Resource name','e.g. Piper')}<label for="type">Resource type</label><select id="type" name="type"><option value="agent" ${selectedType==='agent'?'selected':''}>AI agent</option><option value="robot" ${selectedType==='robot'?'selected':''}>Physical robot</option></select>${input('model','Model or role','e.g. Document analyst')}<label for="capabilities">Primary capability</label><select id="capabilities" name="capabilities">${['analysis','support','classification','inspection','fulfillment'].map(x=>`<option ${x===(selectedType==='robot'?'inspection':'analysis')?'selected':''}>${x}</option>`).join('')}</select><div class="notice">Adds your resource to this workspace using the demo connector. No external service or physical device is connected.</div>${footer('Add custom resource')}</form>`)}
function openDeployment(){let rs=state.resources.filter(r=>r.status==='available');if(!rs.length)return modal('No available resources.',`<p>Complete maintenance, end an existing deployment, or register another resource in the all-customers context.</p><div class="modal-actions"><button class="primary" data-action="close">Got it</button></div>`);modal('Make a resource useful.',`<form data-form="deployment">${input('name','Deployment name','e.g. Daily inventory inspection')}<label for="customerId">Customer</label><select id="customerId" name="customerId">${state.customers.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select><label for="resourceId">Available resource</label><select id="resourceId" name="resourceId">${rs.map(r=>`<option value="${r.id}">${e(r.name)} · ${r.type}</option>`).join('')}</select><label for="capability">Required capability</label><select id="capability" name="capability">${rs[0].capabilities.map(x=>`<option>${x}</option>`).join('')}</select><label class="check"><input type="checkbox" name="confidential">Mask deployment details in the console</label><p>Creates a draft and reserves the resource. Review and activate it before queueing work. Masking is presentational, not encryption.</p>${footer('Create draft assignment')}</form>`)}
function openRun(id){let ds=state.deployments.filter(d=>d.status==='active');if(!ds.length)return modal('Activate a deployment first.','<p>Runs need an active customer deployment and a healthy assigned resource.</p><div class="modal-actions"><button class="primary" data-action="close">Got it</button></div>');modal('Queue the next piece of work.',`<form data-form="run">${input('name','Run name','e.g. Afternoon inspection batch')}<label for="deploymentId">Active deployment</label><select id="deploymentId" name="deploymentId">${ds.map(d=>`<option value="${d.id}" ${d.id===id?'selected':''}>${e(rname(d.resourceId))} · ${e(cname(d.customerId))}</option>`).join('')}</select><div class="notice">A local queue record is created. You’ll manually start and complete the run through the mock connector.</div>${footer('Queue run')}</form>`)}
function openTicket(){modal('Report a customer issue.',`<form data-form="ticket"><label for="customerId">Customer</label><select id="customerId" name="customerId">${state.customers.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select>${input('title','Issue title','e.g. Service report question')}<label for="body">Description</label><textarea id="body" name="body" required maxlength="2000" placeholder="What happened, and what would help?"></textarea><p>Saved to your local support inbox. No external message or AI response is sent.</p>${footer('Save support issue')}</form>`)}
function resolution(kind,id){modal(kind==='incident'?'Resolve operational incident.':'Resolve customer issue.',`<form data-form="resolve" data-kind="${kind}" data-id="${id}"><label for="note">Resolution note</label><textarea id="note" name="note" required maxlength="500" placeholder="Describe the action taken. For demo maintenance, record simulated service completion."></textarea>${footer('Save resolution')}</form>`)}
document.addEventListener('click',async ev=>{if(ev.target.closest('a.skip')){ev.preventDefault();$('#content').focus();return}let b=ev.target.closest('button');if(!b)return;try{if(b.dataset.worktab){workTab=b.dataset.worktab;render();return}if(b.dataset.offer){chooseWork(b.dataset.offer);return}if(b.dataset.workview){workView(b.dataset.workview);return}if(b.dataset.checkout){checkout(b.dataset.checkout);return}if(b.dataset.markettype){marketType=b.dataset.markettype;render();return}if(b.dataset.product){reviewProduct(b.dataset.product);return}if(b.dataset.confirmproduct){let order=await cmd({action:'marketplace.purchase',productId:b.dataset.confirmproduct,paymentMethod:$('#checkout-method').value});modal('Your demo purchase is saved',`<p>${e(order.productName)} is in My purchases. You can now add it to your resources.</p><div class="modal-actions"><button class="secondary" data-action="close">Later</button><button class="primary" data-addpurchase="${order.id}">Add to resources</button></div>`);return}if(b.dataset.addpurchase){let r=await cmd({action:'purchase.add',id:b.dataset.addpurchase});$('#dialog').close();goto('resource/'+r.id);toast('Added to My team.');return}if(b.dataset.openpurchased){$('#dialog').close();goto('resource/'+b.dataset.openpurchased);return}if(b.dataset.customtype){openResource(b.dataset.customtype);return}if(b.dataset.connectperson){await cmd({action:'customer.connect',publicId:b.dataset.connectperson});$('#dialog').close();goto('customers');toast('Connection added by opennoir ID.');return}if(b.dataset.enddeployment){endDeployment(b.dataset.enddeployment);return}if(b.dataset.confirmend){await cmd({action:'deployment.transition',id:b.dataset.confirmend,status:'ended'});$('#dialog').close();toast('Assignment ended. History is retained.');return}if(b.dataset.askassistant){await cmd({action:'assistant.message',body:b.dataset.askassistant});return}if(b.dataset.removescreenshot!==undefined){let [removed]=supportImages.splice(Number(b.dataset.removescreenshot),1);if(removed)URL.revokeObjectURL(removed.preview);render();return}if(b.dataset.incidentdetails){incidentDetails(b.dataset.incidentdetails);return}if(b.dataset.incidentassistant){incidentAssistant(b.dataset.incidentassistant);return}if(b.dataset.incidentstatus){incidentStatus=b.dataset.incidentstatus;render();return}if(b.dataset.incidentseverity){incidentSeverity=b.dataset.incidentseverity;render();return}if(b.dataset.assistantstage){assistantStage=b.dataset.assistantstage;drawIncidentAssistant();return}if(b.dataset.incidentquestion){let i=lookup('incidents',assistantIncidentId);assistantReply=b.dataset.incidentquestion==='cause'?i.events.map(ev=>ev.message).join(' · '):b.dataset.incidentquestion==='priority'?i.severity+' priority · '+(i.kind==='maintenance'?'The resource needs a hardware/service check before working again.':'The failed execution needs review before retrying.'):'After confirmed resolution, check the resource and explicitly reactivate any paused deployment before retrying a failed run.';drawIncidentAssistant();return}if(b.dataset.confirmassistant){let id=assistantIncidentId;await cmd({action:'incident.resolve',id,note:'Mock assistant-guided resolution: simulated diagnostics, service/recovery and verification completed. Operator confirmed. No physical or external commands issued.'});$('#dialog').close();toast('Simulated resolution saved. Review deployment before resuming.');return}if(b.dataset.greet){let r=lookup('resources',b.dataset.greet);if(b.classList.contains('greeting'))return;b.classList.add('greeting');toast(r.status==='maintenance'?r.name+' is resting for maintenance.':r.name+' says hello!');setTimeout(()=>b.classList.remove('greeting'),1600);return}if(b.dataset.editcard){appearance(b.dataset.editcard);return}if(b.dataset.gradient!==undefined){let c=cardDraft[editingCard];c.colors=gradientPresets[Number(b.dataset.gradient)].slice(1);c.mode='gradient';c.overlay=0;showAppearance();return}if(b.dataset.backgroundmode){cardDraft[editingCard].mode=b.dataset.backgroundmode;if(b.dataset.backgroundmode==='gradient')cardDraft[editingCard].overlay=0;showAppearance();return}if(b.dataset.go)return goto(b.dataset.go);if(b.dataset.filter){filter=b.dataset.filter;return render()}if(b.dataset.scope){customer=b.dataset.scope;goto('overview');await load();return}if(b.dataset.newrun)return openRun(b.dataset.newrun);if(b.dataset.resolveincident)return incidentAssistant(b.dataset.resolveincident);if(b.dataset.resolveticket)return resolution('ticket',b.dataset.resolveticket);if(b.dataset.transition){b.disabled=true;await cmd({action:'deployment.transition',id:b.dataset.id,status:b.dataset.transition});return toast('Deployment updated')}if(b.dataset.runstatus){b.disabled=true;await cmd({action:'run.transition',id:b.dataset.id,status:b.dataset.runstatus});return toast(b.dataset.runstatus==='succeeded'&&!state.settings.notifications?'Saved': 'Run updated · '+b.dataset.runstatus)}switch(b.dataset.action){case 'compare-products':modal('Compare demo listings',`<div class="table-wrap"><table><thead><tr><th>Listing</th><th>Company</th><th>Capabilities</th><th>Demo price</th></tr></thead><tbody>${catalogData.map(p=>`<tr><td>${e(p.name)}</td><td>${e(p.vendor)}</td><td>${e(p.capabilities.join(', '))}</td><td>${cash(p.price)}</td></tr>`).join('')}</tbody></table></div><p>Prices are illustrative. Brand references are not official offers.</p>`);break;case 'notifications':notifications();break;case 'read-notifications':await cmd({action:'notifications.read'});notifications();break;case 'demo-payout':await cmd({action:'payout.request'});toast('Simulated payout saved. No money moved.');break;case 'scratch-gradient':Object.assign(cardDraft[editingCard],{mode:'gradient',colors:['#ffffff','#ffffff','#ffffff'],angle:120,shape:'linear',overlay:0});showAppearance();break;case 'toggle-motion':characterMotion=!characterMotion;localStorage.setItem('opennoir-character-motion',characterMotion?'on':'off');render();break;case 'appearance':appearance();break;case 'reset-card':cardDraft[editingCard]=defaultCards()[editingCard];showAppearance();break;case 'clear-scope':customer='';await load();break;case 'browse-market':$('#dialog').close();goto('marketplace');break;case 'upload-support':$('#support-files').click();break;case 'screen-support':await previewScreen();break;case 'capture-support':await captureScreen();break;case 'reload':await load();break;case 'close':$('#dialog').close();break;case 'new-customer':connectPerson();break;case 'connect-person':connectPerson();break;case 'new-resource':openResource();break;case 'add-resource':addResource();break;case 'pair-resource':pairResource();break;case 'my-purchases':myPurchases();break;case 'new-deployment':openDeployment();break;case 'new-run':openRun();break;case 'new-ticket':openTicket();break;case 'export':{let rows=[['Customer','Resource','Run','Status','Attempt','Units','Unit type','Cost USD','Service value USD'],...state.runs.map(r=>[cname(r.customerId),rname(r.resourceId),r.name,r.status,r.attempt,r.units,lookup('resources',r.resourceId)?.type==='robot'?'items':'tokens',r.cost,r.charge])];let csv=rows.map(row=>row.map(x=>'"'+(/^[=+@-]/.test(String(x))?"'"+String(x):String(x)).replace(/"/g,'""')+'"').join(',')).join('\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='opennoir-service-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Service report exported');break}}}catch(err){toast(err.message);await load()}finally{b.disabled=false}});
document.addEventListener('change',async ev=>{if(ev.target.id==='team-status'){teamStatus=ev.target.value;render();return}if(ev.target.id==='market-capability'){marketCapability=ev.target.value;render();return}if(ev.target.id==='market-price'){marketPrice=ev.target.value;render();return}if(ev.target.id==='support-files'){await addSupportImages(Array.from(ev.target.files));return}if(ev.target.id==='market-vendor'){marketVendor=ev.target.value;render();return}if(ev.target.id==='incident-status'){incidentStatus=ev.target.value;render();return}if(ev.target.id==='incident-severity'){incidentSeverity=ev.target.value;render();return}if(ev.target.id==='editing-card'){editingCard=ev.target.value;showAppearance();return}if(ev.target.id==='gradient-shape'){cardDraft[editingCard].shape=ev.target.value;showAppearance();return}if(ev.target.name==='background'){cardDraft[editingCard].image=ev.target.value;previewAppearance();return}if(ev.target.id==='workspace'){workspace=ev.target.value;customer='';localStorage.setItem('opennoir-workspace',workspace);await load()}if(ev.target.id==='customer'){customer=ev.target.value;await load()}if(ev.target.id==='resourceId'){let r=lookup('resources',ev.target.value);$('#capability').innerHTML=r.capabilities.map(x=>`<option>${x}</option>`).join('')}});
document.addEventListener('input',ev=>{if(ev.target.id==='support-message'){supportText=ev.target.value;return}if(ev.target.dataset.color!==undefined){let i=Number(ev.target.dataset.color);cardDraft[editingCard].colors[i]=ev.target.value;document.querySelector('[data-hex="'+i+'"]').value=ev.target.value;previewAppearance();return}if(ev.target.dataset.hex!==undefined){let v=ev.target.value;if(/^#[0-9a-fA-F]{6}$/.test(v)){let i=Number(ev.target.dataset.hex);cardDraft[editingCard].colors[i]=v;$('#gradient-color-'+i).value=v;previewAppearance()}return}if(ev.target.id==='gradient-angle'){cardDraft[editingCard].angle=Number(ev.target.value);$('#angle-output').textContent=ev.target.value+'°';previewAppearance();return}if(ev.target.dataset.adjust){let key=ev.target.dataset.adjust;cardDraft[editingCard][key]=Number(ev.target.value);$('#output-'+key).textContent=ev.target.value+ev.target.dataset.unit;previewAppearance();return}if(ev.target.id==='search'){search=ev.target.value;let pos=ev.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',async ev=>{ev.preventDefault();let form=ev.target,fields=Object.fromEntries(new FormData(form)),button=form.querySelector('button.primary');if(button)button.disabled=true;try{let result;switch(form.dataset.form){case 'finance':await cmd({action:'finance.settings',...fields,privateWorkViews:fields.privateWorkViews==='on'});toast('Payment and privacy preferences saved');return;case 'accept-work':await cmd({action:'work.accept',...fields,confidential:fields.confidential==='on'});$('#dialog').close();workTab='ongoing';goto('deployments');render();toast('Work accepted. Queue a task attempt to begin.');return;case 'visual-support':await saveVisualSupport();return;case 'assistant':await cmd({action:'assistant.message',body:fields.body});return;case 'pair-resource':result=await cmd({action:'resource.pair',...fields});$('#dialog').close();goto('resource/'+result.id);toast('Demo resource connected by ID.');return;case 'lookup-person':{let person=await api('directory/'+encodeURIComponent(fields.publicId.trim().toUpperCase()));if(!['person','business'].includes(person.kind))throw Error('This ID belongs to a resource. Use My team → Add → Connect by ID.');confirmConnection(person);return}case 'operator':await cmd({action:'settings.update',notifications:state.settings.notifications,operatorName:fields.operatorName});toast('Profile saved');return;case 'appearance':await cmd({action:'appearance.update',cards:cardDraft});break;case 'customer':result=await cmd({action:'customer.create',...fields});goto('customers');break;case 'resource':result=await cmd({action:'resource.create',...fields,capabilities:[fields.capabilities]});$('#dialog').close();goto('resources');modal('Your resource is ready',`<p>${e(result.name)} is now in My team with the mock connector.</p><label>opennoir resource ID</label><code class="identity-large">${e(result.publicId)}</code><label>Registration pairing code · shown once</label><code class="identity-large">${e(result.pairingCode)}</code><p>Keep this code private. This local demo does not transfer an already-owned resource to another workspace.</p><div class="modal-actions"><button class="primary" data-action="close">Done</button></div>`);return;case 'deployment':result=await cmd({action:'deployment.create',...fields,confidential:fields.confidential==='on'});workTab='ongoing';goto('deployments');render();break;case 'run':result=await cmd({action:'run.create',...fields});goto('run/'+result.id);break;case 'ticket':result=await cmd({action:'ticket.create',...fields});goto('support');break;case 'resolve':result=await cmd({action:form.dataset.kind+'.resolve',id:form.dataset.id,note:fields.note});break;default:if(form.id==='settings-form'){await cmd({action:'settings.update',...fields,notifications:fields.notifications==='on'});workspaces=await api('workspaces');render();toast('Workspace settings saved');return}}$('#dialog').close();toast('Saved to local workspace')}catch(err){let error=$('#form-error');if(error)error.textContent=err.message;else toast(err.message)}finally{if(button)button.disabled=false}});
$('#dialog').addEventListener('close',()=>stopSupportScreen());
window.addEventListener('hashchange',()=>{if(state)render();window.scrollTo(0,0)});
let marketTab='browse',marketType='all',marketVendor='all',marketCapability='all',marketPrice='all';
function marketplace(){let products=catalogData.filter(p=>(marketType==='all'||p.type===marketType)&&(marketVendor==='all'||p.brand===marketVendor)&&(marketCapability==='all'||p.capabilities.includes(marketCapability))&&(marketPrice==='all'||p.price<=Number(marketPrice)));return heading('A marketplace for what’s next.','Discover robots and AI agents. Bring what you choose into one place.','<button class="secondary" data-action="my-purchases">My purchases · '+(state.purchases?.length||0)+'</button>')+`<div class="notice soft">Demo marketplace · no payment, shipping, AI license, or real device is included. Tesla and NVIDIA names are reference concepts, not verified sellers, partners, or offers.</div><div class="toolbar">${['all','robot','agent'].map(t=>`<button class="pill ${marketType===t?'selected':''}" data-markettype="${t}">${t==='all'?'Everything':t==='robot'?'Robots':'AI agents'}</button>`).join('')}<button class="secondary" data-action="compare-products">Compare listings</button><select id="market-capability" aria-label="Filter by capability"><option value="all">All capabilities</option>${[...new Set(catalogData.flatMap(x=>x.capabilities))].map(c=>`<option ${marketCapability===c?'selected':''}>${e(c)}</option>`).join('')}</select><select id="market-price" aria-label="Filter by price">${[['all','All prices'],['50','Up to $50'],['20000','Up to $20,000']].map(([v,t])=>`<option value="${v}" ${marketPrice===v?'selected':''}>${t}</option>`).join('')}</select><select id="market-vendor" aria-label="Filter marketplace company"><option value="all">All companies</option>${[...new Set(catalogData.map(x=>x.brand))].map(v=>`<option ${marketVendor===v?'selected':''}>${e(v)}</option>`).join('')}</select></div><div class="cards">${products.map(p=>`<article class="panel marketplace-card"><div class="card-top"><span class="eyebrow">${p.type==='robot'?'ROBOT':'AI AGENT'}</span><span class="badge">${p.kind}</span></div><div class="marketplace-image"><img src="assets/${p.image}.png" alt="${e(p.name)} concept" loading="lazy"></div><p class="market-vendor">${e(p.vendor)}</p><h2>${e(p.name)}</h2><p>${e(p.description)}</p><div class="chips">${p.capabilities.map(x=>`<span class="chip">${x}</span>`).join('')}</div><div class="market-price">${cash(p.price)}<span>${p.unit}</span></div><button class="primary full" data-product="${p.id}">View & review</button></article>`).join('')}</div>`}
function reviewProduct(id){let p=catalogData.find(x=>x.id===id);modal('Review your demo purchase',`<div class="purchase-preview"><img src="assets/${p.image}.png" alt="${e(p.name)} concept"><div><h2>${e(p.name)}</h2><p>${e(p.vendor)}</p><p>${cash(p.price)} · illustrative price</p></div></div><div class="notice">This only creates a local demo order. No payment is collected and no robot or AI service is delivered. Brand-reference listings are not official offers.</div><div class="modal-actions"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-checkout="${p.id}">Continue to checkout</button></div>`)}
function myPurchases(){let orders=state.purchases||[];modal('My purchases',`<p>Your demo purchases live here until you add them to My team.</p>${orders.map(o=>`<div class="purchase-row"><div><h3>${e(o.productName)}</h3><p>${e(o.vendor)} · ${cash(o.amount)} · demo</p><small>${e(o.reference||o.id)} · ${date(o.createdAt)}</small></div>${o.resourceId?`<button class="secondary" data-openpurchased="${o.resourceId}">View resource</button>`:`<button class="primary" data-addpurchase="${o.id}">Add to resources</button>`}</div>`).join('')||'<div class="empty">No purchases yet. Browse the marketplace to choose a robot or agent.</div>'}<div class="modal-actions"><button class="secondary" data-action="close">Close</button><button class="primary" data-action="browse-market">Browse marketplace</button></div>`)}
function addResource(){modal('What would you like to add?',`<div class="add-options"><button data-action="my-purchases">${icon('marketplace')}<span>From marketplace<small>Add a robot or agent you purchased in the demo store.</small></span></button><button data-customtype="agent">${icon('agent')}<span>Custom AI agent<small>Register an agent you made and get its opennoir ID.</small></span></button><button data-customtype="robot">${icon('robot')}<span>Custom robot<small>Register your own robot with a local mock connector.</small></span></button><button data-action="pair-resource">${icon('plus')}<span>Connect by ID<small>Use a resource’s opennoir ID and pairing code.</small></span></button></div>`)}
function pairResource(){modal('Connect a resource by ID',`<form data-form="pair-resource">${input('publicId','Resource opennoir ID','ON-R-HARBOR01')}<label for="pairingCode">Pairing code</label><input type="password" id="pairingCode" name="pairingCode" required maxlength="200" autocomplete="off"><div class="notice soft">Local demo example: ON-R-HARBOR01 or ON-A-MIRA0001. Pairing code: DEMO-PAIR-2026. This does not connect physical hardware or external AI.</div>${footer('Connect resource')}</form>`)}
function connectPerson(){modal('Connect by opennoir ID',`<form data-form="lookup-person">${input('publicId','Person or business opennoir ID','ON-P-AVERY001')}<p>Look up the profile first, then confirm who you want to connect. IDs are only searchable in this local demo.</p><div class="notice soft">Try ON-P-AVERY001 for Avery Chen. Existing connections have their ID on their card.</div>${footer('Look up ID')}</form>`)}
function confirmConnection(person){modal('Is this the right connection?',`<span class="profile-mark">${icon('profile')}</span><h2>${e(person.name)}</h2><p>${person.kind==='person'?'Individual':'Business'}</p><code class="identity-large">${e(person.publicId)}</code><p>Connecting lets you assign a resource to work for this person or business. It does not authorize payments or access to their private account.</p><div class="modal-actions"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-connectperson="${person.publicId}">Add connection</button></div>`)}
function endDeployment(id){let d=lookup('deployments',id);modal('End this assignment?',`<h3>${d.confidential?'Confidential assignment':e(d.name)}</h3><p>This ends the ongoing service for ${e(cname(d.customerId))}.</p><ul class="confirmation-list"><li>The resource becomes available for another assignment, unless maintenance still blocks it.</li><li>No new runs can be started under this assignment.</li><li>Past activity, costs and history stay saved.</li><li>This does not delete the resource or issue a real hardware stop command.</li></ul>${state.runs.some(r=>r.deploymentId===id&&['queued','running'].includes(r.status))?'<div class="notice warm">This assignment has queued or running work. Finish or cancel those runs before ending it.</div>':''}<div class="modal-actions"><button class="secondary" data-action="close">Keep assignment</button><button class="danger" data-confirmend="${id}">Yes, end assignment</button></div>`)}
function assistant(){return heading('A little guidance, right here.','Ask about your resources, marketplace, assignments, or activity.')+`<section class="panel assistant-page"><div class="assistant-brand"><img src="assets/agent-nova.png" alt="opennoir assistant mascot"><div><h2>opennoir assistant</h2><p>Scripted demo responses · no live AI connected</p></div></div><div class="assistant-chat-log">${(state.assistantMessages||[]).map(m=>`<div class="chat-message ${m.role}">${e(m.body)}</div>`).join('')||'<div class="chat-message assistant">Hi. I can help you understand how opennoir works. What would you like to explore?</div>'}</div><div class="assistant-prompts">${['What is a run?','How do I buy in Marketplace?','How do opennoir IDs work?','Where do I report an issue?'].map(t=>`<button data-askassistant="${e(t)}">${t}</button>`).join('')}</div><form data-form="assistant" class="assistant-compose"><input name="body" aria-label="Message opennoir assistant" required maxlength="2000" placeholder="Ask a question…"><button class="primary">Send</button></form></section>`}
function guide(){return heading('How opennoir works','Marketplace → My team → Work → Earnings. Everything else helps you manage that journey.')+`<div class="journey-strip">Marketplace <span>→</span> My team <span>→</span> Work <span>→</span> Earnings</div><div class="cards">${[['Marketplace','Browse reference and demo listings, make a simulated purchase, then add it to your resources.'],['My team','Your library of owned or connected robots and AI agents. Add marketplace purchases, your own creations, or an ID-paired demo resource.'],['People & businesses','The people you serve. Find a local demo profile by opennoir ID and connect it before assigning a resource to work for them.'],['Work','Explore demo opportunities or see capability-based recommendations. Choose a team member and client, confirm, then manage ongoing, paused, and completed work.'],['Earnings','Review gross service value, execution costs, a modeled 5% platform fee and net earnings. Simulate a payout and inspect transaction history.'],['Notifications','The header bell shows workspace updates. Activity holds the detailed task timeline.'],['Activity','Each run is one attempt at a task inside an assignment. Review progress, outcome, usage and failures.'],['Reports','See recorded usage, modeled service value and costs. Demo estimates are not invoices or real revenue.'],['Issues & maintenance','Review failed work and maintenance. Follow a guided mock resolution, then decide whether service should resume.'],['Help & support','Explain a problem, attach screenshots, or capture a frame from a screen you choose to share. Save a local support case.'],['Assistant','A place to ask how the app works. Current responses are scripted; a real AI provider is not connected.'],['My account & Settings','Your local opennoir ID, operator name, workspace preferences, card gradients and advanced activity filters.']].map(([t,d])=>`<section class="panel"><h2>${t}</h2><p>${d}</p></section>`).join('')}</div><div class="notice">The current product is a local demo foundation: real saved records and screenshots, simulated purchases and execution, local ID lookup/pairing, and no public sign-in, payments, seller onboarding, remote live support or live AI.</div>`}
let supportText='',supportImages=[],screenStream=null;
function support(){return heading('Show us what’s happening.','Share a screenshot or capture a frame. Keep the context with your support case.')+`<div class="grid support-layout"><section class="panel"><h2>Start with what you can see.</h2><p>Attach up to three PNG, JPEG or WebP screenshots. Each saved image can be up to 2 MB.</p><form data-form="visual-support"><label for="support-message">What’s happening?</label><textarea id="support-message" name="message" maxlength="2000" placeholder="Describe the problem or attach a screenshot…">${e(supportText)}</textarea><input type="file" id="support-files" accept="image/png,image/jpeg,image/webp" multiple hidden><div class="support-attachment-actions"><button class="secondary" type="button" data-action="upload-support">${icon('plus')} Upload screenshots</button><button class="secondary" type="button" data-action="screen-support">Share screen / capture</button></div><div class="support-images">${supportImages.map((im,i)=>`<figure><img src="${im.preview}" alt="Screenshot ready to attach"><button type="button" data-removescreenshot="${i}" aria-label="Remove ${e(im.file.name)}">×</button><figcaption>${e(im.file.name)}</figcaption></figure>`).join('')}</div><p class="small">Screenshots are saved to this local installation only when you submit. Screen sharing creates a local preview; no remote session is opened.</p><button class="primary section">Save support case</button></form></section><section class="panel"><div class="assistant-brand"><img src="assets/agent-nova.png" alt="Assistant mascot"><div><h2>Need help finding the next step?</h2><p>The assistant can explain the app and support flow.</p></div></div><button class="secondary section" data-go="assistant">Chat with opennoir assistant</button><button class="link section" data-go="incidents">View operational incidents</button></section></div><section class="panel section"><div class="panel-head"><h2>Your support cases</h2><span class="muted">${state.tickets.filter(t=>t.status==='open').length} open</span></div>${state.tickets.map(t=>`<article class="support-case"><div class="panel-head"><h3>${e(t.title)}</h3>${badge(t.status)}</div><p>${date(t.createdAt)}</p><p>${e(t.body)}</p><div class="saved-screenshots">${(t.attachments||[]).map(id=>`<a href="/api/attachments/${id}?workspace=${workspace}" target="_blank" rel="noopener"><img src="/api/attachments/${id}?workspace=${workspace}" alt="Attached screenshot — open full image"></a>`).join('')}</div>${t.events.map(ev=>`<p class="small">${e(ev.message)}</p>`).join('')}${t.status==='open'?`<button class="link" data-resolveticket="${t.id}">Add resolution</button>`:''}</article>`).join('')||empty('No support cases yet. Share a problem above to start.')}</section>`}
async function addSupportImages(files){for(let file of files){if(supportImages.length>=3){toast('You can attach up to three screenshots.');break}if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8388608){toast('Choose a PNG, JPEG or WebP under 8 MB.');continue}let signature=new Uint8Array(await file.slice(0,12).arrayBuffer()),actual=signature[0]===137&&signature[1]===80?'image/png':signature[0]===255&&signature[1]===216?'image/jpeg':String.fromCharCode(...signature.slice(0,4))==='RIFF'&&String.fromCharCode(...signature.slice(8,12))==='WEBP'?'image/webp':null;if(!actual){toast('This file is not a supported image.');continue}if(actual!==file.type)file=new File([file],file.name.replace(/\.[^.]+$/,'')+({"image/jpeg":'.jpg',"image/png":'.png',"image/webp":'.webp'}[actual]),{type:actual});if(file.size>2097152){let bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.84));if(!blob||blob.size>2097152){toast('This screenshot is still too large. Choose a smaller image.');continue}file=new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp'})}supportImages.push({file,preview:URL.createObjectURL(file)})}render()}
function stopSupportScreen(){if(screenStream){screenStream.getTracks().forEach(t=>t.stop());screenStream=null}}
async function previewScreen(){if(!navigator.mediaDevices?.getDisplayMedia){toast('Screen capture is unavailable in this browser. Upload a screenshot instead.');return}try{screenStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});modal('Review your shared screen',`<p>Only you can see this local preview. Capture one frame to attach, or close to stop sharing.</p><video id="screen-preview" autoplay muted playsinline></video><div class="modal-actions"><button class="secondary" data-action="close">Stop sharing</button><button class="primary" data-action="capture-support">Capture this frame</button></div>`);$('#screen-preview').srcObject=screenStream;screenStream.getVideoTracks()[0].addEventListener('ended',()=>{screenStream=null;toast('Screen sharing stopped.')},{once:true})}catch(err){stopSupportScreen();toast(err.name==='NotAllowedError'?'Screen sharing was cancelled. You can upload a screenshot instead.':'Screen preview could not start. Upload a screenshot instead.')}}
async function captureScreen(){let video=$('#screen-preview');if(!video?.videoWidth){toast('Wait for the preview to appear.');return}let canvas=document.createElement('canvas'),scale=Math.min(1,1600/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.85));stopSupportScreen();$('#dialog').close();if(blob)await addSupportImages([new File([blob],'screen-capture.webp',{type:'image/webp'})])}
async function saveVisualSupport(){if(!supportText.trim()&&!supportImages.length)throw Error('Describe the problem or attach a screenshot.');let attachments=[];for(let item of supportImages){let data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(item.file)});let saved=await api('attachments',{name:item.file.name,mime:item.file.type,data});attachments.push(saved.id)}let text=supportText.trim()||'Screenshot provided for review';await cmd({action:'ticket.create',customerId:customer||null,title:text.split('\n')[0].slice(0,100),body:text,attachments});for(let item of supportImages)URL.revokeObjectURL(item.preview);supportImages=[];supportText='';render();toast('Support case and screenshots saved locally. No external ticket was sent.')}


let workTab='explore';
const opportunities=[{id:'inspection',name:'Inspect a retail aisle',capability:'inspection',duration:'30 minutes',pay:48,description:'Check a sample aisle and record items needing attention.'},{id:'analysis',name:'Review a document batch',capability:'analysis',duration:'20 minutes',pay:24,description:'Summarize and classify a sample collection of documents.'},{id:'support',name:'Triage customer requests',capability:'support',duration:'15 minutes',pay:18,description:'Sort sample requests and prepare suggested replies.'}];
function deployments(){let tabs=`<div class="toolbar">${['explore','recommended','ongoing','paused','completed'].map(t=>`<button class="pill ${workTab===t?'selected':''}" data-worktab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>`;if(!['explore','recommended'].includes(workTab))return tabs+assignmentCards();let offers=opportunities.filter(o=>workTab!=='recommended'||state.resources.some(r=>r.status==='available'&&r.capabilities.includes(o.capability)));return heading('Find work for your team','Explore sample opportunities, choose a capable team member, and track every task.')+tabs+`<div class="notice soft">Demo opportunities · recommendations use capability matching, not live AI. Estimated earnings are illustrative; accepting a job does not earn money.</div><div class="cards">${offers.map(o=>{let matches=state.resources.filter(r=>r.status==='available'&&r.capabilities.includes(o.capability));return `<article class="panel opportunity-card"><span class="eyebrow">${e(o.capability)} · DEMO WORK</span><h2>${e(o.name)}</h2><p>${e(o.description)}</p><div class="row"><span>Estimated duration</span><span>${o.duration}</span></div><div class="row"><span>Estimated gross</span><span>${cash(o.pay)}</span></div><p class="small">${matches.length?matches.map(r=>e(r.name)).join(', ')+' matches the required '+o.capability+' capability.':'No available team member matches this capability.'}</p><button class="primary full" data-offer="${o.id}" ${!matches.length?'disabled':''}>Review opportunity</button></article>`}).join('')||empty('No matches yet. Add a team member or free one from ongoing work.')}</div>`}
function chooseWork(id){let o=opportunities.find(x=>x.id===id),matches=state.resources.filter(r=>r.status==='available'&&r.capabilities.includes(o.capability));modal('Review work',`<form data-form="accept-work"><input type="hidden" name="offerId" value="${o.id}"><h2>${o.name}</h2><p>${o.description}</p><div class="notice">${o.duration} · ${cash(o.pay)} estimated gross. Actual demo earnings come from completed task attempts, not this estimate. A 5% modeled platform fee applies.</div><label for="work-member">Team member</label><select id="work-member" name="resourceId">${matches.map(r=>`<option value="${r.id}">${e(r.name)}</option>`).join('')}</select><label for="work-client">Work for</label><select id="work-client" name="customerId" required>${state.customers.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select><label class="check"><input type="checkbox" name="confidential">Private work (hide client and work view in the console)</label><p id="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" ${!matches.length||!state.customers.length?'disabled':''}>Confirm and assign</button></div></form>`)}
function workView(id){let d=lookup('deployments',id);if(d.confidential||state.settings.privateWorkViews){modal('Private work',`<p>Work details and visual previews are hidden by your privacy settings or confidentiality agreement.</p><div class="row"><span>Status</span>${badge(d.status)}</div><p class="small">This console masking is not an access-control system. Your local operator retains access to stored records.</p>`);return}let r=lookup('resources',d.resourceId);modal('Work view',`<div class="work-preview">${resourceArt(r)}<span class="badge">Simulated view · ${e(d.status)}</span></div><h2>${e(d.name)}</h2><p>${e(cname(d.customerId))} · ${e(d.capability)}</p><p>This is an animated local preview, not a camera feed.</p>${state.runs.filter(x=>x.deploymentId===id).slice(0,5).map(x=>`<div class="row"><span>${e(x.name)}</span>${badge(x.status)}</div>`).join('')||'<p>No task attempts yet.</p>'}`)}
function earnings(){let gross=state.runs.reduce((n,r)=>n+r.charge,0),cost=state.runs.reduce((n,r)=>n+r.cost,0),fee=gross*.05,net=gross-cost-fee,paid=(state.payouts||[]).reduce((n,p)=>n+p.amount,0);return heading('Earnings','Understand what your team generates, what it costs, and what remains.',`<button class="secondary" data-action="demo-payout" ${customer||net-paid<.01?'disabled':''}>Simulate payout</button>`)+`<div class="notice soft">All amounts are modeled demo values. No real earnings, bank transfers, or tax calculations. Platform fee: 5% of recorded gross service value.</div><div class="stats">${metric('Gross service value',cash(gross),'Recorded task attempts','reports')}${metric('Operating costs',cash(cost),'Mock execution costs','reports')}${metric('Platform fees',cash(fee),'Modeled 5% fee','reports')}${metric('Net earnings',cash(net),'Gross minus costs and fees','reports')}</div><div class="split section"><section class="panel"><h2>By team member</h2>${state.resources.map(r=>{let rs=state.runs.filter(x=>x.resourceId===r.id),n=rs.reduce((a,x)=>a+x.charge*.95-x.cost,0);return `<div class="row"><span>${e(r.name)}</span><span>${cash(n)}</span></div>`}).join('')}</section><section class="panel"><h2>Demo balance</h2><div class="metric">${cash(Math.max(0,net-paid))}</div><p>Available for a simulated payout</p><h2>Payout history</h2>${(state.payouts||[]).map(p=>`<div class="row"><span>${date(p.createdAt)} · ${e(p.method)}</span><span>${cash(p.amount)} · simulated</span></div>`).join('')||'<p>No simulated payouts yet.</p>'}</section></div><section class="panel section"><h2>Work transactions</h2>${state.runs.map(r=>`<div class="row"><span>${lookup('deployments',r.deploymentId)?.confidential?'Confidential task':e(r.name)} · ${e(r.status)}</span><span>${cash(r.charge*.95-r.cost)} net</span></div>`).join('')}</section>`}
function checkout(id){let p=catalogData.find(x=>x.id===id);modal('Demo checkout',`<h2>${e(p.name)}</h2><div class="row"><span>Total · illustrative price</span><span>${cash(p.price)}</span></div><label for="checkout-method">Demo payment method</label><select id="checkout-method"><option value="demo-card">Demo card · no card details</option><option value="demo-wallet" ${state.settings.paymentMethod==='demo-wallet'?'selected':''}>Demo wallet</option></select><div class="notice section">No payment will be collected. This saves a simulated order only; no product, license, or shipment is included.</div><div class="modal-actions"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-confirmproduct="${p.id}">Place simulated order</button></div>`)}
function notifications(){let cutoff=state.settings.notificationsReadAt||'',events=state.events.filter(x=>x.type!=='notifications.read').slice(0,20);modal('Notifications',`<p>Workspace updates and issues. For task history, open Activity.</p><button class="secondary" data-action="read-notifications">Mark all as read</button>${events.map(x=>`<div class="activity"><span class="event-dot"></span><div><p>${x.at>cutoff?'● ':''}${e(x.message)}</p><time>${date(x.at)}</time></div></div>`).join('')||'<p>No notifications yet.</p>'}`)}
function financeSettings(){return `<section class="panel section"><h2>Payments, payouts & privacy</h2><p>Demo preferences only. Do not enter real card or banking details.</p><form data-form="finance"><label for="finance-payment">Payment method</label><select id="finance-payment" name="paymentMethod"><option value="demo-card">Demo card</option><option value="demo-wallet" ${state.settings.paymentMethod==='demo-wallet'?'selected':''}>Demo wallet</option></select><label for="finance-payout">Payout destination</label><select id="finance-payout" name="payoutMethod"><option value="demo-wallet">Demo wallet</option><option value="demo-bank" ${state.settings.payoutMethod==='demo-bank'?'selected':''}>Demo bank</option></select><label class="check"><input type="checkbox" name="privateWorkViews" ${state.settings.privateWorkViews?'checked':''}>Hide all visual work previews</label><button class="secondary section" ${customer?'disabled':''}>Save preferences</button></form></section>`}

feedback=createFeedback({getState:()=>state?{...state,feedback:reviewComments}:undefined,getCustomer:()=>customer,command:async data=>{for(let attempt=0;attempt<2;attempt++){try{let result=await api('commands',{...data,revision:state.revision});await load();return result.result}catch(err){if(err.status===409&&attempt===0){await load();continue}throw err}}},notify:toast,navigate:async note=>{customer=note.customerId||'';location.hash=note.route;await load()}});
try{workspaces=await api('workspaces');if(!workspaces.some(w=>w.id===workspace))workspace=workspaces[0].id;await load()}catch(err){$('#content').innerHTML=`<section class="panel"><h1>Start the local server.</h1><p>${e(err.message)}</p><p>This product requires its Node API. See the included setup guide.</p></section>`}

// Decorative pointer interaction; no resource commands are issued.
document.addEventListener('pointermove',ev=>{let b=ev.target.closest('.art-interactive');if(!b||!characterMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let rect=b.getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width-.5,y=(ev.clientY-rect.top)/rect.height-.5;b.style.setProperty('--tilt-x',(-y*9)+'deg');b.style.setProperty('--tilt-y',(x*12)+'deg')});
document.addEventListener('pointerout',ev=>{let b=ev.target.closest('.art-interactive');if(b&&!b.contains(ev.relatedTarget)){b.style.setProperty('--tilt-x','0deg');b.style.setProperty('--tilt-y','0deg')}});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',ev=>{if(ev.matches){characterMotion=false;document.body.classList.remove('character-motion');if(state)render()}});
